  }
  return ''
})

// 监听器
watch(() => appStore.isSamePath, async () => {
  loading.value = true
  userList.value = ''
  resetParams()
  let ust = JSON.parse(localStorage.getItem('userInfo'))
  logInfo.value = ust
  userInfo.value = ust
  if (ust.role == 4 && !router.currentRoute.value.params.pid) {
    getRoleInfo(ust.id)
    params.object.type = 0
    return
  }
  userName.value = userInfo.value.account
  userRole.value = userInfo.value.layer
  listInfo.value = userInfo.value
  id.value = router.currentRoute.value.params.pid ? router.currentRoute.value.params.pid : ust.id
  getUserInfo(id.value)
})

// 方法
const tsztab = (num) => {
  tstatus.value = num
}

const yyueTab = (item) => {
