}

const canTabs = async (item) => {
  try {
    // 1. 等待弹窗确认（点击“是”才会继续，点“否”会抛出异常）
    await showConfirmDialog({
      message: `是否取消当前账号(${item.account})状态预约。`,
      title: '提示',
      confirmButtonText: '是',
      cancelButtonText: '否',
    });
    // 2. 执行取消逻辑
    const res = await userStore.delStatusFuture(item.id);
    showToast({ type: 'success', message: res.data });
    
    // 3. 刷新列表
    userList.value = [];
    moreShow.value = false;
    await getUserList(); // 如果该方法是异步，建议加 await
    
  } catch (error) {
     getUserList()
