}

const pktab = () => {
  zdSelect.value = true
}
const staTab = () =>{
  zdSelect.value = false
  staShow.value = false
  moreShow.value = false
  showDialog2.value = false
  showDialog3.value = false
  logshow.value = false
  logall.value = false
}
const sztab = (num) => {
  params.object.status = num
  pages.pageNum = 1
  zdSelect.value = false
  userList.value = []
  getUserList()
}

const moTab = (item) => {
  moreShow.value = true
  uitem.value = item
}

const getWidth = () => {
  if (occupyList.value[0]?.occupy.length > 3 && occupyList.value[0]?.occupy.length < 8) {
    return 'width:680px'
  } else if (occupyList.value[0]?.occupy.length > 8) {
    return 'width:1380px'
  } else {
    return 'width:355px'
  }
}

const checkedRow = (m) => {
  userNum.value = m
}

const confirmTime = (val, field) => {
  const time = formatTime(val)
  if (time) {
    listQuery.object[field] = time
  }
  cancelTime()
}

const getclist = () => {
  listQuery.object.start = ''
  listQuery.object.end = ''
}

const logcurChange = (val) => {
  listQuery.pageNum = val
  getlogs()
}

const formatTime = (date) => {
  const seperator1 = "-"
  let year = date.getFullYear()
  let month = date.getMonth() + 1
  let strDate = date.getDate()
  
  if (month >= 1 && month <= 9) {
    month = "0" + month
  }
  if (strDate >= 0 && strDate <= 9) {
    strDate = "0" + strDate
  }
  return year + seperator1 + month + seperator1 + strDate
}

const cancelTime = () => {
  showStart.value = false
  showEnd.value = false
}

const clearList = () => {
  listQuery.object = {
    start: '',
    end: '',
    operId: '',
    assignedId: '',
    ip: '',
    modType: '',
    controlType: '',
    funType: ''
  }
  listQuery.pageNum = 0
  listQuery.pageSize = 25
  listQuery.total = 0
}

const logtab = (obj, num) => {
  loglist.value = []
  clearList()
  if (num == 1) {
    listQuery.object.assignedId = obj.id
    logall.value = true
  } else {
    listQuery.object.assignedId = obj.id
    listQuery.object.modType = 3
    listQuery.object.funType = 7
    logshow.value = true
  }
  getlogs()
}

const getlogs = async () => {
  let t1 = ""
  let t2 = ""
  
  if (listQuery.object.start) {
    t1 = listQuery.object.start + ' 00:00:00'
  }
  if (listQuery.object.end) {
    t2 = listQuery.object.end + ' 23:59:59'
  }
  
  const bbb = {
    object: {
      start: t1,
      end: t2,
      operId: listQuery.object.operId,
      assignedId: listQuery.object.assignedId,
      ip: listQuery.object.ip,
      modType: listQuery.object.modType,
      controlType: listQuery.object.controlType,
      funType: listQuery.object.funType
    },
    pageNum: listQuery.pageNum,
    pageSize: listQuery.pageSize,
  }
  
  try {
    const res = await userStore.getPageLogs(bbb)
    res.data.list.map(item => {
      if (item.origin) {
        if (item.origin.indexOf(',') >= 0) {
          item.orlist = item.origin.split(",")
        } else {
          item.orlist = []
          item.orlist.push(item.origin)
        }
      }
      if (item.changed) {
        if (item.changed.indexOf(',') >= 0) {
          item.chlist = item.changed.split(",")
        } else {
          item.chlist = []
          item.chlist.push(item.changed)
        }
      }
    })
    loglist.value = res.data.list
    listQuery.pageSize = res.data.pageSize
    listQuery.total = res.data.total
  } catch (error) {
    console.log('获取日志失败')
  }
}

const isDot = (num) => {
  let result = (num.toString()).indexOf(".")
  if (result != -1) {
    return num.toFixed(1)
  } else {
    return num
  }
}

const changeType = (obj) => {
  if (obj == 4) {
    router.push('/subAccount')
  } else {
    setType(obj)
  }
}

const setType = (num) => {
  resetParams()
  params.object.type = num
  if (num == 0) {
    params.object.layer = 100
    params.object.role = 3
  } else if (num == 1) {
    params.object.layer = 100
    params.object.role = 5
  } else if (num == 2) {
    params.object.layer = 1000
    params.object.role = 3
  } else if (num == 3) {
    params.object.layer = 1000
    params.object.role = 5
  } else if (num == 5) {
    params.object.layer = 2
    params.object.role = 2
  }
  pages.pageNum = 0
  params.object.accountId = listInfo.value.id
  userList.value = []
  getUserList()
}

const typeAndIdByNext = (num, item) => {
  if (item.role == 5) {
    return false
  }
  listInfo.value = item
  userRole.value = item.layer
  userName.value = item.account
  params.object.type = num
  params.pageNum = 0
  if (num == 2) {
    params.object.layer = 1000
    params.object.role = 3
  } else if (num == 3) {
    params.object.layer = 1000
    params.object.role = 5
  }
  id.value = item.id
  params.object.accountId = item.id
  userList.value = []
  getUserList()
}

const ocpTab = (items, type) => {
    showDialog3.value = true;
    occupyDetails.value = items.roleName + '-' + items.account + '占成明细'
    getOccupy(items.id)
}

const cashTab = (items, type, num) => {
  userPassName.value = items.account
  dataParams.amount = ''
  beyond.value = false
  dataParams.accountId = items.id
  selectUserInfo.username = items.account
  selectUserInfo.role = items.layer
  selectUserInfo.mode = items.mode
  selectUserInfo.type = num
  selectUserInfo.types = type
  selectUserInfo.id = items.id
  getQuotaFind()
}

const getQuotaFind = async () => {
  try {
    const res = await userStore.getQuota(selectUserInfo.id)
    if (res.code == 200) {
      dataParams.type = res.data.type
      selectUserInfo.cash = res.data.limit
      showDialog2.value = true
      upLevelAmount.value = res.data.upLimit
    }
  } catch (error) {
    console.log('获取配额失败')
  }
}

const changeOn = () => {
  beyond.value = false
  if (Number(dataParams.amount) > Number(upLevelAmount.value) && dataParams.ops == '1') {
    beyond.value = true
  } else if (showDialog2.value && Number(dataParams.amount) > Number(selectUserInfo.cash) && dataParams.ops == '2') {
    beyond.value = true
  } else {
    beyond.value = false
  }
}

const closeDialog = () => {
  selectUserInfo.username = ''
  selectUserInfo.credit = ''
  selectUserInfo.cash = ''
  selectUserInfo.role = ''
  selectUserInfo.type = ''
  selectUserInfo.types = ''
  selectUserInfo.id = ''
  
  dataParams.ops = ''
  dataParams.type = ''
  dataParams.amount = ''
  
  showDialog1.value = false
  showDialog2.value = false
  showDialog3.value = false
  changePword.value = false
  upLevelAmount.value = ''
}

const sortKey = (array, key) => {
  return array.sort((a, b) => {
    const x = a[key]
    const y = b[key]
    return ((x < y) ? -1 : (x > y) ? 1 : 0)
  })
}

const getOccupy = async (id) => {
  occupyList.value = []
  try {
    const res = await userStore.getsOccupy(id)
    res.data.map(item => {
      item.occupy = sortKey(item.occupy, 'lotteryId')
    })
    occupyList.value = res.data
  } catch (error) {
    console.log('获取占成失败')
  }
}

const qdan = async () => {
  if (loading.value) return false
  
  loading.value = true
  setTimeout(() => {
    loading.value = false
  }, 3000)
  
  const getDate = {
    type: dataParams.type,
    accountId: dataParams.accountId
  }
  
  showdio.value = false
  
  try {
    const res = await userStore.getDrawall(getDate)
    if (res.code == 200) {
      showDialog1.value = false
      showDialog2.value = false
      loading.value = false
      showToast({ type: 'success', message: res.message })
      userList.value = []
      getUserList()
    } else {
      showToast({ type: 'error', message: res.message })
    }
  } catch (error) {
    console.log('提取额度失败')
  }
}

const extractAll = () => {
  showdio.value = true
}

const confirmAmount = async (type) => {
  if (loading.value) return false
  
  loading.value = true
  setTimeout(() => {
    loading.value = false
  }, 3000)
  
  if (!dataParams.ops) {
    showToast({ type: 'error', message: '请选择类型!' })
    return
  }
  
  if (dataParams.ops == '1') {
    if (dataParams.amount > upLevelAmount.value) {
      showToast({ type: 'error', message: '输入的额度不能超过上级额度!' })
      return
    }
  }
  
  if (dataParams.ops == '2') {
    if (dataParams.amount > selectUserInfo.cash && type == 'cashAmount') {
      showToast({ type: 'error', message: '输入的额度不能超过当前额度!' })
      return
    }
  }
  
  try {
    const res = await userStore.getQuotaupdate(dataParams)
    if (res.code == 200) {
      showDialog1.value = false
      showDialog2.value = false
      loading.value = false
      showToast({ type:'success', message: res.data })
      userList.value = []
      getUserList()
    } else {
      showToast({ type: 'error', message: res.data })
    }
  } catch (error) {
    console.log('更新配额失败')
  }
}

const enableStatus = async (item) => {
  loading.value = true
  const { id, status, role } = item
  
  try {
    await showConfirmDialog({
        title: '是否修改该用户状态。',
        messageAlign: 'center',  // 设置 message 居中
        width: '85vw',  
    })
    const res = await userStore.getStatus(id, status)
    userList.value = []
    showToast({ 
      type: res.data != "上级代理状态不正常，请联系上级代理处理~" ? 'success' : 'error', 
      message: res.data 
    })
    loading.value = false
    getUserList()
  } catch (error) {
    getUserList()
    loading.value = false
  }
}

const entryUpLevel = (items) => {
  if (items.pid === userInfo.value.id) {
    return
  }
  resetParams()
  params.object.type = 0
  getPidInfo(items.pid)
}

const getPidInfo = async (id) => {
  try {
    const res = await userStore.getAuthInfo(id)
    listInfo.value = res.data
    const str = res.data
    userRole.value = str.layer - 1
    userName.value = str.account
    
    if (str.layer > 2 && str.layer < 13) {
      params.object.layer = 100
      params.object.role = 0
    } else if (str.layer == 2) {
      params.object.layer = 100
      params.object.role = 0
    } else if (str.layer == 13) {
      params.object.layer = 100
      params.object.role = 0
    }
    params.object.accountId = str.pid
    userList.value = []
    getUserList()
    getwzList(str.pid)
  } catch (error) {
    console.log('获取用户信息失败')
  }
}

const entryBackLevel = (items) => {
  listInfo.value = items
  if (items.id === userInfo.value.id) {
    return
  }
  resetParams()
  params.object.type = 0
  params.pageNum = 0
  pages.pageNum = 0
  getUserInfo(items.pid)
  getwzList(items.pid)
}

const getUserInfo = async (ids) => {
  try {
    const res = await userStore.getAuthInfo(ids)
    listInfo.value = res.data
    id.value = res.data.id
    userRole.value = res.data.layer
    userName.value = res.data.account
    if (res.data.layer >= 2 && res.data.layer < 13) {
      params.object.layer = 100
      params.object.role = 0
    } else if (res.data.layer == 1) {
      params.object.layer = 100
      params.object.role = 0
    } else if (res.data.layer == 13) {
      params.object.layer = 100
      params.object.role = 0
    }
    params.object.accountId = res.data.id
    userList.value = []
    getUserList()
    getwzList(res.data.id)
  } catch (error) {
    console.log('获取用户信息失败')
  }
}

const entryNextLevel = (items) => {
  listInfo.value = items
  if ([1, 3].includes(params.object.type)) {
    return
  }
  resetParams()
  
  if (items.layer == 2) {
    params.object.layer = 100
    params.object.role = 0
  } else if (params.layer == 12) {
    params.object.layer = 100
    params.object.role = 0
  } else {
    params.object.layer = 100
    params.object.role = 0
  }
  id.value = items.id
  userRole.value = items.layer
  userName.value = items.account
  params.object.accountId = items.id
  pages.pageNum = 1
  userList.value = []
  getUserList()
  getwzList(items.id)
}

const handleSizeChange = (val) => {
  console.log(`每页 ${val} 条`)
}

const handleCurrentChange = (val) => {
  pages.pageNum = val
  userList.value = []
  getUserList()
}

const resetError = async (item) => {
  try {
    const res = await userStore.getLoginFalseCount(item.id)
    showToast({ type: res.code == 200 ? 'success' : 'error', message: res.data })
    loading.value = false
    userList.value = []
    getUserList()
  } catch (error) {
    loading.value = false
  }
}

const getwzList = async (id) => {
  loading.value = true
  try {
    const res = await userStore.getAcc(id)
    loading.value = false
    wzlist.value = res.data
  } catch (error) {
    loading.value = false
  }
}
// 上拉加载时触发
const onLoad = () =>{
	// 模拟异步加载数据
	setTimeout(() => {
	  getUserList();
	}, 1000);
}
const getUserList = async () => {
  loading.value = true
  params.pageNum = pages.pageNum ? pages.pageNum : 0
  try {
    const res = await userStore.getUserList(params)
    userList.value = userList.value.concat(res.data.list);
	if (res.data.list.length < pages.pageSize) {
		finished.value = true;
	} else {
		pages.pageNum++;
	}
    loading.value = false
   // userList.value = res.data.list
    pages.pageSize = res.data.pageSize
    pages.total = res.data.total
  } catch (error) {
    loading.value = false
    userList.value = { user: [] }
  }
}

const resetParams = () => {
  params.object = {
    type: 5,
    status: 1,
    account: '',
    accountId: '',
    layer: '',
    role: ''
  }
  params.pageNum = 0
  params.pageSize = 25
}

const getRoleInfo = async (obj) => {
  try {
    const res = await userStore.getAuthInfo(obj)
    userName.value = res.data.account
    userRole.value = res.data.layer - 1
    res.data.id = res.data.pid
    res.data.layer = res.data.layer - 1
    res.data.role = res.data.role - 1
    userInfo.value = res.data
    getUserInfo(res.data.pid)
  } catch (error) {
    console.log('获取角色信息失败')
  }
}

// 生命周期
onMounted(() => {
  let ust = JSON.parse(localStorage.getItem('userInfo'))
  logInfo.value = ust
  userInfo.value = ust
  if (ust.role == 4 && !router.currentRoute.value.params.pid) {
    getRoleInfo(ust.id)
    params.object.type = 0
    return
  }
  userName.value = userInfo.value.account
  userRole.value = userInfo.value.layer
  listInfo.value = userInfo.value
  id.value = router.currentRoute.value.params.pid ? router.currentRoute.value.params.pid : ust.id
  getUserInfo(id.value)
})
</script>
